import{_ as i,c as t,o,ae as n}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"ENSURING COMMERCIAL, COST-EFFECTIVE SOLUTIONS IN FEDERAL CONTRACTS","description":"","frontmatter":{"title":"ENSURING COMMERCIAL, COST-EFFECTIVE SOLUTIONS IN FEDERAL CONTRACTS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/ensuring-commercial-cost-effective-solutions-in-federal-contracts/","publishDate":"2025-04-16T12:51:27-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-16-ensuring-commercial-cost-effective-solutions-in-federal-contracts.md","filePath":"executive-orders/2025-04-16-ensuring-commercial-cost-effective-solutions-in-federal-contracts.md"}'),r={name:"executive-orders/2025-04-16-ensuring-commercial-cost-effective-solutions-in-federal-contracts.md"};function s(a,e,l,c,u,p){return o(),t("div",null,e[0]||(e[0]=[n('<h1 id="ensuring-commercial-cost-effective-solutions-in-federal-contracts" tabindex="-1">ENSURING COMMERCIAL, COST-EFFECTIVE SOLUTIONS IN FEDERAL CONTRACTS <a class="header-anchor" href="#ensuring-commercial-cost-effective-solutions-in-federal-contracts" aria-label="Permalink to &quot;ENSURING COMMERCIAL, COST-EFFECTIVE SOLUTIONS IN FEDERAL CONTRACTS&quot;">​</a></h1><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/ensuring-commercial-cost-effective-solutions-in-federal-contracts/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/ensuring-commercial-cost-effective-solutions-in-federal-contracts/</a></p><p>Published: 2025-04-16T12:51:27-04:00</p><ul><li><p><strong>Objective</strong>: Eliminate unnecessary taxpayer expenditures and improve government procurement practices.</p></li><li><p><strong>Key Issues Identified</strong>:</p><ul><li>Previous administrations favored custom products over commercially available solutions, leading to increased spending and delays.</li><li>A lack of integration of commercial innovations in government procurement.</li></ul></li><li><p><strong>Policy Directive</strong>:</p><ul><li>Agencies are required to use commercially available products and services whenever possible, in line with the Federal Acquisition Streamlining Act of 1994 (FASA).</li></ul></li><li><p><strong>Definitions</strong>:</p><ul><li><strong>Agency</strong>: Includes executive departments, military departments, independent establishments, and wholly owned government corporations.</li><li><strong>Approval authority</strong>: Senior procurement executive responsible for acquisition management.</li><li><strong>Contracting officer</strong>: Defined in federal regulations.</li></ul></li><li><p><strong>Agency Responsibilities</strong>:</p><ul><li><p><strong>60-day Requirement</strong>: Review all existing solicitations for non-commercial products/services and consolidate findings for approval.</p><ul><li>Must include market research and price analysis justifying the need for non-commercial products/services.</li></ul></li><li><p><strong>30-day Assessment</strong>: Approval authority must evaluate compliance with FASA and recommend alternatives when deficiencies are found.</p></li><li><p><strong>120-day Reporting</strong>: Agencies must report annually to the Office of Management and Budget (OMB) on compliance with FASA and implementation progress.</p></li></ul></li><li><p><strong>Proposal Process</strong>:</p><ul><li><p>For non-commercial products/services solicitations, contracting officers must submit a detailed proposal to the approval authority.</p><ul><li>The proposal must include market research and price analysis.</li></ul></li><li><p>The approval authority can seek input from the Director of OMB on the proposal validity.</p></li></ul></li><li><p><strong>Implementation Notes</strong>:</p><ul><li>The order does not limit the authority of executive departments or the functions of the OMB.</li><li>Implementation is subject to existing laws and appropriations.</li><li>The order does not create enforceable rights for individuals against the U.S. government or its entities.</li></ul></li></ul>',4)]))}const f=i(r,[["render",s]]);export{m as __pageData,f as default};
